            if (rr, cc) in comp['cells']:
                orig_pattern[(rr-comp['min_r'], cc-comp['min_c'])] = comp['color']

    new_start_row = current_row
    current_row += comp['height']

    for dr, dc in orig_pattern:
        pred_r = new_start_row + dr
        pred_c = comp['min_c'] + dc
        prediction[pred_r][pred_c] = comp['color']

# Simpler approach for others: just place each in first available row maintaining column span
for comp in other_comps:
    # Find first empty row that can accommodate this component's bbox at its column span
    for start_row in range(7, 9):  # Middle band
        can_fit = True
        for dr in range(comp['height']):
            for dc in range(comp['width']):
                if (comp['min_r']+dr, comp['min_c']+dc) in comp['cells']:
                    if prediction[start_row+dr][comp['min_c']+dc] != 0:
